function validate([seats]) {
  if (!Array.isArray(seats) || seats.length < 1 || seats.length > 8) return 'seats needs 1 to 8 rows.';
  const n = Array.isArray(seats[0]) ? seats[0].length : 0;
  if (n < 1 || n > 8) return 'Each row needs 1 to 8 seats.';
  for (const row of seats) {
    if (!Array.isArray(row) || row.length !== n) return 'Every row must have the same number of seats.';
    if (row.some(cell => cell !== '.' && cell !== '#')) return "Each seat is '.' (usable) or '#' (broken).";
  }
  return null;
}

