function maxStudents(seats) {
  const rows = seats.length;
  const cols = seats[0].length;
  const full = 1 << cols;
  let prev = new Array(full).fill(-1);
  prev[0] = 0;
  for (let r = 0; r < rows; r++) {
    let open = 0;
    for (let c = 0; c < cols; c++) {
      if (seats[r][c] === '.') {
        open |= 1 << c;
      }
    }
    const curr = new Array(full).fill(-1);
    for (let mask = 0; mask < full; mask++) {
      if ((mask & open) !== mask || (mask & (mask << 1)) !== 0) {
        continue;
      }
      let count = 0;
      for (let bits = mask; bits > 0; bits &= bits - 1) {
        count++;
      }
      for (let above = 0; above < full; above++) {
        if (prev[above] < 0) {
          continue;
        }
        if ((mask & (above << 1)) !== 0 || (mask & (above >> 1)) !== 0) {
          continue;
        }
        curr[mask] = Math.max(curr[mask], prev[above] + count);
      }
    }
    prev = curr;
  }
  return Math.max(...prev);
}

