function maxStudents(seats) {
  // Seats in even and odd columns form a bipartite "can see" graph, so by König's theorem the
  // answer is the number of usable seats minus a maximum matching (found with Kuhn's algorithm).
  const m = seats.length, n = seats[0].length;
  const usable = (r, c) => r >= 0 && r < m && c >= 0 && c < n && seats[r][c] === '.';
  const neighbors = (r, c) => [[r, c - 1], [r, c + 1], [r - 1, c - 1], [r - 1, c + 1], [r + 1, c - 1], [r + 1, c + 1]].filter(([a, b]) => usable(a, b));
  const partner = new Map();
  function augment(r, c, visited) {
    for (const [a, b] of neighbors(r, c)) {
      const key = a * n + b;
      if (visited.has(key)) continue;
      visited.add(key);
      if (!partner.has(key) || augment(...partner.get(key), visited)) {
        partner.set(key, [r, c]);
        return true;
      }
    }
    return false;
  }
  let total = 0, matched = 0;
  for (let r = 0; r < m; r++) {
    for (let c = 0; c < n; c++) {
      if (!usable(r, c)) continue;
      total++;
      if (c % 2 === 0 && augment(r, c, new Set())) matched++;
    }
  }
  return total - matched;
}

