function generate(rand, size) {
  const m = size === 'large' ? 6 + Math.floor(rand() * 3) : 1 + Math.floor(rand() * 4);
  const n = size === 'large' ? 6 + Math.floor(rand() * 3) : 1 + Math.floor(rand() * 4);
  const broken = [0, 0.15, 0.3, 0.5, 0.8][Math.floor(rand() * 5)];
  const seats = [];
  for (let r = 0; r < m; r++) {
    const row = [];
    for (let c = 0; c < n; c++) row.push(rand() < broken ? '#' : '.');
    seats.push(row);
  }
  return [seats];
}
